mapper.select:
SELECT COUNT(*)
FROM TB_BALANCE
WHERE USER_ID = #{userId}

SELECT SEQ AS seq, USER_ID AS userId, BALANCE AS balance, TOTAL_BALANCE AS totalBalance, OPERATION AS operation, COMMENT AS comment, REG_DATE AS regDate FROM TB_BALANCE WHERE USER_ID = #{userId} AND OPERATION = 'P'
AND DATE(REG_DATE) >= #{startDate}
AND DATE(REG_DATE) <= #{endDate}
ORDER BY SEQ DESC
